class CliError(Exception):
    def __init__(self, message: str, code: int = 2):
        super().__init__(message)
        self.message = message
        self.code = code

class AppError(Exception):
    def __init__(self, message: str, cause: Optional[str] = None, code: int = 1):
        super().__init__(message)
        self.message = message
        self.cause = cause
        self.code = code

# ---- clap-like text helpers -------------------------------------------------

def help_text(prog: str) -> str:
    return f"""Ping, but with a graph.

Usage: {prog} [OPTIONS] [HOSTS_OR_COMMANDS]...

Arguments:
  [HOSTS_OR_COMMANDS]...  Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1

Options:
      --cmd
          Graph the execution time for a list of commands rather than pinging hosts
  -n, --watch-interval <WATCH_INTERVAL>
          Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5
  -b, --buffer <BUFFER>
          Determines the number of seconds to display in the graph [default: 30]
  -4
          Resolve ping targets to IPv4 address
  -6
          Resolve ping targets to IPv6 address
  -i, --interface <INTERFACE>
          Interface to use when pinging
  -s, --simple-graphics

      --vertical-margin <VERTICAL_MARGIN>
          Vertical margin around the graph (top and bottom) [default: 1]
      --horizontal-margin <HORIZONTAL_MARGIN>
          Horizontal margin around the graph (left and right) [default: 0]
  -c, --color <color>
          Assign color to a graph entry.

          This option can be defined more than once as a comma separated string, and the
          order which the colors are provided will be matched against the hosts or
          commands passed to gping.

          Hexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the
          following color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',
          'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',
          'light-blue', 'light-magenta', 'light-cyan', and 'white'
      --clear
          Clear the graph from the terminal after closing the program
      --ping-args [<PING_ARGS>...]
          Extra arguments to pass to `ping`. These are platform dependent
  -h, --help
          Print help
  -V, --version
          Print version
"""

def cli_usage(prog: str, specific: Optional[str] = None, positional: bool = True) -> str:
    if specific:
        suffix = " [HOSTS_OR_COMMANDS]..." if positional else ""
        # For conflict messages clap renders a required positional placeholder.
        if specific in ("-4", "-6"):
            return f"Usage: {prog} {specific} <HOSTS_OR_COMMANDS>..."
        return f"Usage: {prog} {specific}{suffix}"
    return f"Usage: {prog} [OPTIONS] [HOSTS_OR_COMMANDS]..."

def fmt_cli_error(prog: str, first: str, body: Optional[str] = None, usage_specific: Optional[str] = None) -> str:
    parts = [f"error: {first}"]
    if body:
        parts.append(body.rstrip("\n"))
    parts.append(cli_usage(prog, usage_specific))
    parts.append("For more information, try '--help'.")
    return "\n\n".join(parts) + "\n"

def unexpected_arg(prog: str, arg: str) -> CliError:
    suggestion = similar_long(arg)
    if suggestion:
        usage = suggestion
        val = suggestion.split()[0]
        body = f"  tip: a similar argument exists: '{val}'\n"
        return CliError(fmt_cli_error(prog, f"unexpected argument '{arg}' found", body, usage), 2)
    body = f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n"
    return CliError(fmt_cli_error(prog, f"unexpected argument '{arg}' found", body), 2)

def similar_long(arg: str) -> Optional[str]:
    mapping = {
        "--ver": "--version",
        "--vers": "--version",
        "--versi": "--version",
        "--versio": "--version",
        "--hel": "--help",
        "--he": "--help",
        "--wat": "--watch-interval <WATCH_INTERVAL>",
        "--watch": "--watch-interval <WATCH_INTERVAL>",
        "--watch-i": "--watch-interval <WATCH_INTERVAL>",
        "--colo": "--color <color>",
        "--col": "--color <color>",
        "--buff": "--buffer <BUFFER>",
        "--inter": "--interface <INTERFACE>",
    }
    return mapping.get(arg)

def duplicate_error(prog: str, canonical: str) -> CliError:
    return CliError(fmt_cli_error(prog, f"the argument '{canonical}' cannot be used multiple times"), 2)

def missing_value(prog: str, canonical: str) -> CliError:
    return CliError(f"error: a value is required for '{canonical}' but none was supplied\n\nFor more information, try '--help'.\n", 2)

def invalid_value(prog: str, val: str, canonical: str, why: str) -> CliError:
    return CliError(f"error: invalid value '{val}' for '{canonical}': {why}\n\nFor more information, try '--help'.\n", 2)

def unexpected_value(prog: str, val: str, opt: str) -> CliError:
    return CliError(fmt_cli_error(prog, f"unexpected value '{val}' for '{opt}' found; no more were expected", usage_specific=opt), 2)

# ---- parsing ----------------------------------------------------------------

def parse_float_value(prog: str, val: str) -> float:
    try:
        # Rust's f64 parser accepts NaN/inf with these spellings.
        if val.lower() == "nan":
            return float("nan")
        if val.lower() in ("inf", "+inf", "infinity", "+infinity"):
            return float("inf")
        if val.lower() in ("-inf", "-infinity"):
            return float("-inf")
        return float(val)
    except Exception:
        raise invalid_value(prog, val, "--watch-interval <WATCH_INTERVAL>", "invalid float literal")

def parse_usize(prog: str, val: str, canonical: str) -> int:
    if not re.fullmatch(r"[0-9]+", val or ""):
        raise invalid_value(prog, val, canonical, "invalid digit found in string")
    try:
        n = int(val)
    except Exception:
        raise invalid_value(prog, val, canonical, "number too large to fit in target type")
    # Match common 64-bit clap behavior.
    if n > 2**64 - 1:
        raise invalid_value(prog, val, canonical, "number too large to fit in target type")
    return n

def parse_u16(prog: str, val: str, canonical: str) -> int:
    try:
        n = int(val, 10)
    except Exception:
        raise invalid_value(prog, val, canonical, "invalid digit found in string")
    if n < 0 or n > 65535:
        raise invalid_value(prog, val, canonical, f"{val} is not in 0..=65535")
    return n

def check_once(prog: str, seen: set, key: str):
    if key in seen:
        raise duplicate_error(prog, CANONICAL[key])
    seen.add(key)

def set_ip(prog: str, opts: Options, seen: set, key: str):
    flag = "-4" if key == "ipv4" else "-6"
    other = "ipv6" if key == "ipv4" else "ipv4"
    otherflag = "-6" if key == "ipv4" else "-4"
    if key in seen:
        raise duplicate_error(prog, flag)
    if other in seen:
        # clap's message names the earlier argument first
        earlier = otherflag
        later = flag
        raise CliError(fmt_cli_error(prog, f"the argument '{earlier}' cannot be used with '{later}'", usage_specific=earlier), 2)
    seen.add(key)
    setattr(opts, key, True)

def parse_args(argv: List[str], prog: str) -> Options:
    opts = Options()
    seen: set = set()
    i = 0
    stop_options = False
    while i < len(argv):
        tok = argv[i]
        if stop_options:
            opts.targets.append(tok)
            i += 1
            continue
        if tok == "--":
            stop_options = True
            i += 1
            continue
        # Long options
        if tok.startswith("--") and tok != "--":
            opt, eq, val = tok.partition("=")
            if opt not in LONG_OPTIONS:
                raise unexpected_arg(prog, opt if not eq else tok)
            if opt in ("--help", "--version", "--cmd", "--simple-graphics", "--clear"):
                if eq:
                    raise unexpected_value(prog, val, opt)
                if opt == "--help":
                    print(help_text(prog), end="")
                    raise SystemExit(0)
                if opt == "--version":
                    print(VERSION_LONG, end="")
                    raise SystemExit(0)
                key = {"--cmd":"cmd", "--simple-graphics":"simple_graphics", "--clear":"clear"}[opt]
                check_once(prog, seen, key)
                setattr(opts, key, True)
                i += 1
                continue
            if opt == "--ping-args":
                if eq:
                    opts.ping_args.append(val)
                    i += 1
                else:
                    # This variadic option consumes the rest of argv exactly as values.
                    opts.ping_args.extend(argv[i+1:])
                    i = len(argv)
                continue
            # valued long options
            if not eq:
                if i + 1 >= len(argv):
                    canonical = {
                        "--watch-interval": "--watch-interval <WATCH_INTERVAL>",
                        "--buffer": "--buffer <BUFFER>",
                        "--interface": "--interface <INTERFACE>",
                        "--vertical-margin": "--vertical-margin <VERTICAL_MARGIN>",
                        "--horizontal-margin": "--horizontal-margin <HORIZONTAL_MARGIN>",
                        "--color": "--color <color>",
                    }[opt]
                    raise missing_value(prog, canonical)
                if argv[i+1].startswith("-"):
                    raise unexpected_arg(prog, argv[i+1])
                val = argv[i+1]
                i += 2
            else:
                i += 1
            if opt == "--watch-interval":
                check_once(prog, seen, "watch_interval")
                opts.watch_interval_src = val
                opts.watch_interval = parse_float_value(prog, val)
            elif opt == "--buffer":
                check_once(prog, seen, "buffer")
                opts.buffer = parse_usize(prog, val, "--buffer <BUFFER>")
            elif opt == "--interface":
                check_once(prog, seen, "interface")
                opts.interface = val
            elif opt == "--vertical-margin":
                check_once(prog, seen, "vertical_margin")
                opts.vertical_margin = parse_u16(prog, val, "--vertical-margin <VERTICAL_MARGIN>")
            elif opt == "--horizontal-margin":
                check_once(prog, seen, "horizontal_margin")
                opts.horizontal_margin = parse_u16(prog, val, "--horizontal-margin <HORIZONTAL_MARGIN>")
            elif opt == "--color":
                opts.color_values.append(val)
            continue
        # Short options/clusters. A bare '-' is positional.
        if tok.startswith("-") and tok != "-":
            # A negative-looking bare token is an unexpected argument unless after --.
            j = 1
            while j < len(tok):
                ch = tok[j]
                if ch == "h":
                    print(help_text(prog), end="")
                    raise SystemExit(0)
                if ch == "V":
                    print(VERSION_SHORT + "\n", end="")
                    raise SystemExit(0)
                if ch == "4":
                    set_ip(prog, opts, seen, "ipv4")
                    j += 1
                    continue
                if ch == "6":
                    set_ip(prog, opts, seen, "ipv6")
                    j += 1
                    continue
                if ch == "s":
                    check_once(prog, seen, "simple_graphics")
                    opts.simple_graphics = True
                    j += 1
                    continue
                if ch in ("n", "b", "i", "c"):
                    # The rest of the cluster is the attached value; if empty use next token.
                    rest = tok[j+1:]
                    if rest.startswith("="):
                        val = rest[1:]
                    elif rest:
                        val = rest
                    else:
                        canonical = {"n":"--watch-interval <WATCH_INTERVAL>", "b":"--buffer <BUFFER>", "i":"--interface <INTERFACE>", "c":"--color <color>"}[ch]
                        if i + 1 >= len(argv):
                            raise missing_value(prog, canonical)
                        if argv[i+1].startswith("-"):
                            raise unexpected_arg(prog, argv[i+1])
                        val = argv[i+1]
                        i += 1
                    if ch == "n":
                        check_once(prog, seen, "watch_interval")
                        opts.watch_interval_src = val
                        opts.watch_interval = parse_float_value(prog, val)
                    elif ch == "b":
                        check_once(prog, seen, "buffer")
                        opts.buffer = parse_usize(prog, val, "--buffer <BUFFER>")
                    elif ch == "i":
                        check_once(prog, seen, "interface")
                        opts.interface = val
                    elif ch == "c":
                        opts.color_values.append(val)
                    # value option consumes the whole token.
                    break
                # Unknown short option: clap reports just the offending flag, not the whole cluster.
                raise unexpected_arg(prog, "-" + ch)
            i += 1
            continue
        # Positional host/command
        opts.targets.append(tok)
        i += 1
    return opts

# ---- colors and target preparation -----------------------------------------

def split_color_values(values: List[str]) -> List[str]:
    out: List[str] = []
    for v in values:
        out.extend(v.split(","))
    return out

def parse_color(raw: str) -> Color:
    # Hex colors are accepted only in exact #RRGGBB form at the start of the segment.
    if raw.startswith("#"):
        if re.fullmatch(r"#[0-9a-fA-F]{6}", raw):
            return Color("rgb", (int(raw[1:3], 16), int(raw[3:5], 16), int(raw[5:7], 16)), raw)
        raise AppError(f"Invalid color code: `{raw}`", "Failed to parse Colors")
    s = raw.strip()
    norm = s.lower().replace("_", "-")
    if norm in COLOR_NAMES:
        return Color("idx", COLOR_NAMES[norm], raw)
    # Allow compact spellings like lightred/darkgray.
    compact = norm.replace("-", "")
    if compact in COLOR_NAMES:
        return Color("idx", COLOR_NAMES[compact], raw)
    raise AppError(f"Invalid color code: `{raw}`", "Failed to parse Colors")

def colors_for_targets(opts: Options, count: int) -> List[Color]:
    raw_colors = split_color_values(opts.color_values)
    colors: List[Color] = []
    for idx in range(count):
        if idx < len(raw_colors):
            colors.append(parse_color(raw_colors[idx]))
        else:
            colors.append(Color("idx", DEFAULT_COLORS[idx % len(DEFAULT_COLORS)]))
    return colors

def expand_cloud(host: str) -> str:
    if host.startswith("aws:"):
        return "ec2." + host.split(":", 1)[1] + ".amazonaws.com"
    if host.startswith("gcp:"):
        return "storage." + host.split(":", 1)[1] + ".rep.googleapis.com"
    return host

@dataclass
class PreparedTarget:
    label_host: str
    ping_host: str
    resolved_ip: str


def resolve_one(host: str, opts: Options) -> PreparedTarget:
    expanded = expand_cloud(host)
    try:
        all_infos = socket.getaddrinfo(expanded, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
    except socket.gaierror as e:
        reason = getattr(e, 'strerror', None) or "Name or service not known"
        raise AppError(f"Resolving {expanded}", f"failed to lookup address information: {reason}")
    if opts.ipv4:
        infos = [x for x in all_infos if x[0] == socket.AF_INET]
        if not infos:
            raise AppError(f"Could not resolve '{expanded}' to IPv4", None)
    elif opts.ipv6:
        infos = [x for x in all_infos if x[0] == socket.AF_INET6]
        if not infos:
            raise AppError(f"Could not resolve '{expanded}' to IPv6", None)
    else:
        infos = all_infos
        if not infos:
            raise AppError(f"Resolving {expanded}", "failed to lookup address information: Name or service not known")
    sockaddr = infos[0][4]
    ip = sockaddr[0]
    return PreparedTarget(label_host=expanded, ping_host=expanded, resolved_ip=ip)

# ---- data model -------------------------------------------------------------

@dataclass
class Series:
    name: str
    color: Color
    values: List[Tuple[float, Optional[float]]] = field(default_factory=list)
    timeouts: int = 0
    lock: threading.Lock = field(default_factory=threading.Lock)

    def add_value(self, val: Optional[float]):
        now = time.time()
        with self.lock:
            self.values.append((now, val))
            # keep a generous number; draw prunes by time window
            cutoff = now - 3600
            if len(self.values) > 5000:
                self.values = self.values[-5000:]
            elif self.values and self.values[0][0] < cutoff:
                self.values = [(t, v) for t, v in self.values if t >= cutoff]
            if val is None:
                self.timeouts += 1

    def snapshot(self, window: float) -> Tuple[List[Tuple[float, Optional[float]]], int]:
        now = time.time()
        cutoff = now - window
        with self.lock:
            vals = [(t, v) for t, v in self.values if t >= cutoff]
            return vals, self.timeouts

# ---- ping / command workers -------------------------------------------------

def interval_for(opts: Options) -> float:
    if opts.watch_interval is not None:
        try:
            val = float(opts.watch_interval)
            if math.isnan(val):
                return 0.0
            if val < 0:
                return max(0.0, val)
            return val
        except Exception:
            return 0.0
    return 0.5 if opts.cmd else 0.2

def interval_arg_value(opts: Options) -> str:
    val = interval_for(opts)
    if math.isinf(val):
        # mimic the saturating conversion observed for +inf closely enough
        val = float(2**64 - 1) / 1000.0
    if math.isnan(val):
        val = 0.0
    return f"{val:.1f}"

PING_TIME_RE = re.compile(r"(?:time|time=)[=<]?\s*([0-9]+(?:\.[0-9]+)?)(?:\s*)(ms|msec|s|us|µs)?", re.I)

def parse_ping_line(line: str) -> Tuple[bool, Optional[float]]:
    low = line.lower()
    if "no answer yet" in low or "request timeout" in low or "timed out" in low:
        return True, None
    m = PING_TIME_RE.search(line)
    if not m:
        return False, None
    val = float(m.group(1))
    unit = (m.group(2) or "ms").lower()
    if unit in ("us", "µs"):
        sec = val / 1_000_000.0
    elif unit == "s":
        sec = val
    else:
        sec = val / 1000.0
    return True, sec

def spawn_ping_processes(opts: Options, prepared: List[PreparedTarget], series: List[Series]) -> List[subprocess.Popen]:
    procs: List[subprocess.Popen] = []
    for target, ser in zip(prepared, series):
        # The observed Linux binary probes `ping -V` before each target.
        try:
            ver = subprocess.run(["ping", "-V"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        except FileNotFoundError:
            raise AppError("Error spawning ping: No such file or directory (os error 2)", "No such file or directory (os error 2)")
        cmd_name = "ping6" if opts.ipv6 else "ping"
        args = [cmd_name, "-O", "-i" + interval_arg_value(opts)]
        if opts.interface is not None:
            args.extend(["-I", opts.interface])
        args.extend(opts.ping_args)
        args.append(target.ping_host)
        try:
            p = subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
        except FileNotFoundError:
            raise AppError("Error spawning ping: No such file or directory (os error 2)", "No such file or directory (os error 2)")
        procs.append(p)
        def reader(proc: subprocess.Popen, s: Series):
            try:
                assert proc.stdout is not None
                for line in proc.stdout:
                    ok, val = parse_ping_line(line)
                    if ok:
                        s.add_value(val)
            except Exception:
                pass
        threading.Thread(target=reader, args=(p, ser), daemon=True).start()
    return procs

def split_command(command: str) -> Optional[List[str]]:
    try:
        parts = shlex.split(command)
    except ValueError:
        # The observed UI continues to draw malformed strings as failed commands.
        return [command]
    if not parts:
        return None
    return parts

def panic_empty_command():
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at gping/src/main.rs:269:10:\n")
    sys.stderr.write("Must specify a command to watch\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def start_command_workers(opts: Options, series: List[Series]) -> List[threading.Thread]:
    interval = interval_for(opts)
    if interval < 0 or math.isnan(interval):
        interval = 0.0
    threads: List[threading.Thread] = []
    for cmd_str, ser in zip(opts.targets, series):
        parts = split_command(cmd_str)
        if parts is None:
            panic_empty_command()
        def worker(parts: List[str], s: Series):
            next_run = time.monotonic()
            while True:
                now = time.monotonic()
                if now < next_run:
                    time.sleep(min(0.05, next_run - now))
                    continue
                start = time.monotonic()
                ok = False
                try:
                    res = subprocess.run(parts, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    ok = (res.returncode == 0)
                except Exception:
                    ok = False
                elapsed = time.monotonic() - start
                if ok:
                    s.add_value(elapsed)
                else:
                    # Failed commands are drawn at zero with no successful statistics.
                    s.add_value(None)
                step = interval if interval > 0 else 0.0
                next_run = start + step
                if step == 0.0:
                    time.sleep(0.02)
        t = threading.Thread(target=worker, args=(parts, ser), daemon=True)
        t.start()
        threads.append(t)
    return threads

# ---- terminal drawing -------------------------------------------------------

def duration_str(sec: float) -> str:
    if sec is None or math.isnan(sec):
        return "0ns"
    if sec < 0:
        sec = 0
    if sec < 1e-6:
        return f"{int(round(sec * 1e9))}ns"
    if sec < 1e-3:
        us = sec * 1e6
        if us >= 100:
            return f"{us:.0f}µs"
        if us >= 10:
            return f"{us:.1f}".rstrip('0').rstrip('.') + "µs"
        return f"{us:.2f}".rstrip('0').rstrip('.') + "µs"
    if sec < 1:
        ms = sec * 1000
        if ms >= 100:
            s = f"{ms:.3f}".rstrip('0').rstrip('.')
        elif ms >= 10:
            s = f"{ms:.3f}".rstrip('0').rstrip('.')
        else:
            s = f"{ms:.3f}".rstrip('0').rstrip('.')
        return s + "ms"
    if sec < 60:
        return f"{sec:.3f}".rstrip('0').rstrip('.') + "s"
    if sec < 3600:
        return f"{sec/60:.3f}".rstrip('0').rstrip('.') + "min"
    return f"{sec/3600:.3f}".rstrip('0').rstrip('.') + "h"

def stat_values(vals: List[Tuple[float, Optional[float]]]) -> List[float]:
    return [v for _, v in vals if v is not None]

def p95(values: List[float]) -> float:
    if len(values) < 2:
        return 0.0
    arr = sorted(values)
    # nearest-rank-ish, but keep first sample behavior as 0 like the observed program
    idx = int(math.ceil(0.95 * len(arr))) - 1
    idx = max(0, min(idx, len(arr)-1))
    return arr[idx]

def jitter(values: List[float]) -> float:
    if len(values) < 2:
        return 0.0
    diffs = [abs(values[i] - values[i-1]) for i in range(1, len(values))]
    return sum(diffs) / len(diffs)

def trim_to_width(s: str, width: int) -> str:
    if width <= 0:
        return ""
    # Python len is codepoints; good enough for the ASCII-heavy labels used here.
    if len(s) > width:
        return s[:width]
    return s + " " * (width - len(s))

def cursor(row: int, col: int) -> str:
    return f"\x1b[{max(1,row)};{max(1,col)}H"

def clear_screen() -> str:
    return "\x1b[2J"

def reset_hide() -> str:
    return "\x1b[39m\x1b[49m\x1b[0m\x1b[?25l"

def draw_frame(series: List[Series], opts: Options, rows: int, cols: int, start_time: float) -> str:
    if rows <= 0 or cols <= 0:
        return reset_hide()
    window = max(float(opts.buffer), 0.0)
    now = time.time()
    top = opts.vertical_margin + 1
    left_margin = opts.horizontal_margin
    # Keep first frame similar: blank screen then cursor-addressed drawing.
    out: List[str] = ["\x1b[H", clear_screen()]
    # snapshots and global y scale
    snapshots = [s.snapshot(window) for s in series]
    all_success = []
    for vals, _ in snapshots:
        all_success.extend(stat_values(vals))
    if all_success:
        mn = min(all_success)
        mx = max(all_success)
        if mx <= mn:
            pad = max(mx * 0.071, 1e-9)
            ymin, ymax = max(0.0, mn - pad), mx + pad
        else:
            pad = (mx - mn) * 0.10
            ymin, ymax = max(0.0, mn - pad), mx + pad
    else:
        ymin, ymax = 0.0, 1e-9
    # Headers
    header_width = max(10, min(28, cols // 4))
    for idx, (s, snap) in enumerate(zip(series, snapshots)):
        row = top + idx
        if row > rows:
            break
        vals, tcount = snap
        successes = stat_values(vals)
        name = s.name
        if successes:
            last = successes[-1]
            stats = (
                f"last {duration_str(last):<8}"
                f"min {duration_str(min(successes)):<8}"
                f"max {duration_str(max(successes)):<8}"
                f"avg {duration_str(sum(successes)/len(successes)):<8}"
                f"jtr {duration_str(jitter(successes)):<8}"
                f"p95 {duration_str(p95(successes)):<8}"
                f"t/o {tcount:<4}"
            )
        else:
            stats = ""
        line = trim_to_width(name, header_width) + stats
        out.append(cursor(row, 1 + left_margin) + s.color.ansi() + trim_to_width(line, max(0, cols-left_margin)))
    # Graph area
    graph_top = top + len(series)
    graph_bottom = rows - opts.vertical_margin - 1
    if graph_bottom < graph_top:
        graph_bottom = rows - 2 if rows >= 3 else rows
    axis_row = min(rows, graph_bottom + 1)
    label_w = 8
    graph_left = label_w + 1 + opts.horizontal_margin
    graph_right = max(graph_left + 1, cols - opts.horizontal_margin)
    graph_h = max(1, graph_bottom - graph_top + 1)
    graph_w = max(1, graph_right - graph_left)
    # y-axis labels and axis lines
    for r in range(graph_h):
        row = graph_top + r
        frac = 1.0 - (r / max(1, graph_h - 1))
        val = ymin + frac * (ymax - ymin)
        lab = duration_str(val)
        out.append(cursor(row, 1 + opts.horizontal_margin) + "\x1b[39;49m" + trim_to_width(lab, label_w))
        out.append(cursor(row, graph_left) + "\x1b[38;5;7;49m" + "│")
    out.append(cursor(axis_row, graph_left) + "\x1b[38;5;7;49m" + "└" + "─" * max(0, graph_w-1))
    # X axis timestamps: now-window, center, now
    for pos, ts in [(0, now-window), (graph_w//2, now-window/2), (max(0, graph_w-8), now)]:
        txt = time.strftime("%H:%M:%S", time.localtime(ts))
        col = min(cols - len(txt) + 1, graph_left + pos)
        out.append(cursor(axis_row+1 if axis_row < rows else axis_row, col) + "\x1b[39;49m" + txt)
    # Plot points. One char per sample bucket; draw in insertion order.
    char = "•" if opts.simple_graphics else "⠂"
    for s, snap in zip(series, snapshots):
        vals, _ = snap
        for ts, val in vals:
            if ts < now - window:
                continue
            xfrac = 1.0 if window <= 0 else (ts - (now-window)) / window
            x = int(max(0, min(graph_w-1, round(xfrac * (graph_w-1)))))
            vv = 0.0 if val is None else val
            if ymax <= ymin:
                yfrac = 0.5
            else:
                yfrac = (vv - ymin) / (ymax - ymin)
            yfrac = max(0.0, min(1.0, yfrac))
            y = int(round((1.0 - yfrac) * (graph_h - 1)))
            out.append(cursor(graph_top + y, graph_left + 1 + x) + s.color.ansi() + char)
    out.append(reset_hide())
    return "".join(out)

class TerminalMode:
    def __init__(self):
        self.fd = None
        self.old = None
    def __enter__(self):
        if not (sys.stdin.isatty() and sys.stdout.isatty()):
            raise AppError("No such device or address (os error 6)", None)
        self.fd = sys.stdin.fileno()
        try:
            self.old = termios.tcgetattr(self.fd)
            tty.setcbreak(self.fd)
        except Exception:
            self.old = None
        return self
    def __exit__(self, exc_type, exc, tb):
        if self.fd is not None and self.old is not None:
            try:
                termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old)
            except Exception:
                pass

def run_tui(series: List[Series], opts: Options):
    with TerminalMode():
        rows, cols = shutil.get_terminal_size((0, 0))
        sys.stdout.write(f"\x1b[8;{rows};{cols}t" + clear_screen() + "\x1b[?25l")
        sys.stdout.flush()
        start = time.time()
        last_draw = 0.0
        try:
            while True:
                # handle input
                try:
                    r, _, _ = select.select([sys.stdin], [], [], 0.05)
                    if r:
                        ch = os.read(sys.stdin.fileno(), 32)
                        if any(c in ch for c in (b"q", b"Q", b"\x1b", b"\x03")):
                            break
                except Exception:
                    pass
                now = time.monotonic()
                if now - last_draw >= 0.2:
                    rows, cols = shutil.get_terminal_size((rows, cols))
                    sys.stdout.write(draw_frame(series, opts, rows, cols, start))
                    sys.stdout.flush()
                    last_draw = now
        except KeyboardInterrupt:
            pass
        finally:
            rows, cols = shutil.get_terminal_size((0, 0))
            if opts.clear:
                sys.stdout.write("\x1b[?25h\x1b[H" + clear_screen())
            else:
                sys.stdout.write("\x1b[?25h" + cursor(rows + 1, cols + 1))
            sys.stdout.flush()

# ---- app main ---------------------------------------------------------------

def print_app_error(e: AppError):
    sys.stderr.write(f"Error: {e.message}\n")
    if e.cause:
        sys.stderr.write(f"\nCaused by:\n    {e.cause}\n")

def prepare_series(opts: Options) -> Tuple[List[Series], List[PreparedTarget]]:
    if not opts.targets:
        raise AppError(NO_TARGET_ERROR[7:] if NO_TARGET_ERROR.startswith("Error: ") else NO_TARGET_ERROR, None)
    # Validate colors per target, in target order. Extra colors are ignored.
    raw_colors = split_color_values(opts.color_values)
    series: List[Series] = []
    prepared: List[PreparedTarget] = []
    for idx, target in enumerate(opts.targets):
        color = parse_color(raw_colors[idx]) if idx < len(raw_colors) else Color("idx", DEFAULT_COLORS[idx % len(DEFAULT_COLORS)])
        if opts.cmd:
            name = target
        else:
            pt = resolve_one(target, opts)
            prepared.append(pt)
            name = f"{pt.label_host} ({pt.resolved_ip})"
        series.append(Series(name=name, color=color))
    return series, prepared

def main(argv: List[str]) -> int:
    prog = os.path.basename(sys.argv[0]) or "executable"
    try:
        opts = parse_args(argv, prog)
        if not opts.targets:
            raise AppError("At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.")
        series, prepared = prepare_series(opts)
        procs: List[subprocess.Popen] = []
        if opts.cmd:
            # command workers start only after a terminal is successfully opened; but empty command panics first.
            # Check for empty commands to mimic the observed panic.
            for t in opts.targets:
                if split_command(t) is None:
                    panic_empty_command()
            # Color validation has already happened; now require a terminal, then start workers.
            with TerminalMode():
                start_command_workers(opts, series)
                # run the same loop body, but TerminalMode is already active; use a small nested variant
                rows, cols = shutil.get_terminal_size((0, 0))
                sys.stdout.write(f"\x1b[8;{rows};{cols}t" + clear_screen() + "\x1b[?25l")
                sys.stdout.flush()
                start = time.time(); last_draw = 0.0
                try:
                    while True:
                        try:
                            r, _, _ = select.select([sys.stdin], [], [], 0.05)
                            if r:
                                ch = os.read(sys.stdin.fileno(), 32)
                                if any(c in ch for c in (b"q", b"Q", b"\x1b", b"\x03")):
                                    break
                        except Exception:
                            pass
                        now = time.monotonic()
                        if now - last_draw >= 0.2:
                            rows, cols = shutil.get_terminal_size((rows, cols))
                            sys.stdout.write(draw_frame(series, opts, rows, cols, start))
                            sys.stdout.flush(); last_draw = now
                except KeyboardInterrupt:
                    pass
                finally:
                    rows, cols = shutil.get_terminal_size((0, 0))
                    if opts.clear:
                        sys.stdout.write("\x1b[?25h\x1b[H" + clear_screen())
                    else:
                        sys.stdout.write("\x1b[?25h" + cursor(rows + 1, cols + 1))
                    sys.stdout.flush()
        else:
            procs = spawn_ping_processes(opts, prepared, series)
            try:
                run_tui(series, opts)
            finally:
                for p in procs:
                    try:
                        p.terminate()
                    except Exception:
                        pass
        return 0
    except CliError as e:
        sys.stderr.write(e.message)
        return e.code
    except AppError as e:
        print_app_error(e)
        return e.code
    except SystemExit as e:
        raise

if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stderr.close()
        except Exception:
            pass
        sys.exit(1)
